import{_ as t,H as l,f as r,b as e,j as _}from"./chunks/framework.BH2BK_3i.js";const I=JSON.parse('{"title":"Q42 | 潜力：AI算法+后端工程师的应用场景","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q42｜潜力：AI算法+后端工程师的应用场景.md","filePath":"致程序员：AI百问百答/Q42｜潜力：AI算法+后端工程师的应用场景.md","lastUpdated":1795559851000}'),n={name:"致程序员：AI百问百答/Q42｜潜力：AI算法+后端工程师的应用场景.md"};function o(s,a,d,i,p,c){return l(),r("div",null,[...a[0]||(a[0]=[e("h1",{id:"q42-潜力-ai算法-后端工程师的应用场景",tabindex:"-1"},[_("Q42 | 潜力：AI算法+后端工程师的应用场景 "),e("a",{class:"header-anchor",href:"#q42-潜力-ai算法-后端工程师的应用场景","aria-label":'Permalink to "Q42 | 潜力：AI算法+后端工程师的应用场景"'},"​")],-1),e("ul",null,[e("li",null,"作者介绍：Tyler，前亚马逊应用科学家，头部大厂 AIGC 算法技术负责人")],-1),e("p",null,"Q：未来 3-5 年懂算法的后端工程师会在什么样的场景中发挥巨大价值？",-1),e("p",null,"Tyler：不知道你有没有想过一个问题，就是这一轮的人工智能发展到最后是一个什么状态。可能大部分工作都会变成数字员工的形式，这些数字员工的背后对应的就是一个个的智能体。我们在对智能体建模的过程中就类似用一个 job model 去描述这个智能体，我们用智能体来替代社会上各种劳动力的过程里，就会衍生出各种智能体开发的需求。",-1),e("p",null,"你有没有想过，当一个平台上有上千万个智能体同时运作的时候， 底层的服务架构是什么样的，这需要多少个后端工程师才能完成工作。 如果你希望有机会去支撑这个多智能体系统，也是需要你提前对这个系统有所了解，不可能直接让做业务开发的同学去管理和改造多智能体系统，这肯定是不行的，这个过程中肯定是会有一些无形的门槛。",-1),e("p",null,"如果说未来三到五年，再让我做一个预测的话，我认为用数字员工替代劳动力的过程中所产生的多智能体是需要大量的 AI 系统工程师或者后端工程师去支撑的。所以大家不用有类似“汽车出现了之后，我们马车夫怎么办”这样的忧虑，因为我们跟马车夫和汽车司机还是不太一样的，我们本质上是一个工程师，我们只不过从后端工程师转到了 AI 系统工程师，是去支撑一个更大的目标而已。所以我觉得在这个过程里，我们可以主动向前多迈一步，就能提前占据一个很好的位置。",-1)])])}const u=t(n,[["render",o]]);export{I as __pageData,u as default};
